python3 - <<'PY'
import json, pathlib
p = pathlib.Path.home()/"Library/Application Support/com.robotsandpencils.XcodesApp/available-xcodes.json"
d = json.loads(p.read_text())
print("keys:", list(d[0].keys()))
def label(x):
    v = x.get("version", {})
    if isinstance(v, dict):
        n = v.get("number","?")
        r = v.get("release", {})
        if r.get("release"): k="RELEASE"
        elif r.get("gm"): k="GM"
        elif r.get("gmSeed"): k="GM seed %s"%r.get("gmSeed")
        elif r.get("rc"): k="RC %s"%r.get("rc")
        elif r.get("beta"): k="beta %s"%r.get("beta")
        else: k=str(r)
        return n,k,x.get("releaseDate")
    return str(v),"?",None
out=[]
for x in d:
    n,k,dt = label(x)
    if n.startswith("27") or n.startswith("26.6") or n.startswith("26.5"):
        out.append((n,k,dt))
for n,k,dt in out[:30]:
    print(f"{n:10} {k:14} {dt}")
PY

